function design(site, analyse) {
  const xs = [0, 3.483, 6.967, 10.45, 13.933, 17.417, 20.9];
  const nodes = [];
  const members = [];

  const top = "AL7075 CHS323.9x10";
  const bottom = "AL7075 CHS219.1x8";
  const web = "AL7075 CHS193.7x6.3";
  const vertical = "AL7075 CHS168.3x5";
  const transverse = "AL7075 CHS168.3x5";
  const crossFrame = "AL7075 CHS193.7x6.3";
  const planeBrace = "AL7075 CHS193.7x6.3";

  function add(a, b, spec) {
    members.push({ a, b, spec });
  }

  for (let i = 0; i < xs.length; i++) {
    nodes.push({ id: `BL${i}`, x: xs[i], y: -3.35, z: -2.65 });
    nodes.push({ id: `BR${i}`, x: xs[i], y: -3.35, z: 2.65 });
  }

  for (let i = 0; i < 6; i++) {
    add(`L${i}`, `L${i + 1}`, top);
    add(`R${i}`, `R${i + 1}`, top);
    add(`BL${i}`, `BL${i + 1}`, bottom);
    add(`BR${i}`, `BR${i + 1}`, bottom);

    // Pratt diagonals slope toward midspan on each side truss.
    if (i < 3) {
      add(`L${i}`, `BL${i + 1}`, web);
      add(`R${i}`, `BR${i + 1}`, web);
    } else {
      add(`BL${i}`, `L${i + 1}`, web);
      add(`BR${i}`, `R${i + 1}`, web);
    }

    // One diagonal in each top and bottom horizontal panel.
    add(`L${i}`, `R${i + 1}`, planeBrace);
    add(`BL${i}`, `BR${i + 1}`, planeBrace);
  }

  for (let i = 0; i < 7; i++) {
    add(`L${i}`, `BL${i}`, vertical);
    add(`R${i}`, `BR${i}`, vertical);

    add(`L${i}`, `R${i}`, transverse);
    add(`BL${i}`, `BR${i}`, transverse);

    // Triangulate each transverse frame, alternating orientation.
    if (i % 2 === 0) {
      add(`L${i}`, `BR${i}`, crossFrame);
    } else {
      add(`R${i}`, `BL${i}`, crossFrame);
    }
  }

  return {
    note: "Twin below-deck Pratt trusses use pinned aluminium tubes, with transverse frames and braced top and bottom planes for three-dimensional stability.",
    nodes,
    members
  };
}

function design(site, analyse) {
  const xs = [0, 3.483, 6.967, 10.45, 13.933, 17.417, 20.9];

  // Ordered from lightest to heaviest; the dominated CHS139.7x6.3
  // option is omitted so section searches remain monotonic.
  const sections = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94],
    ["CHS48.3x3.2", 4.53], ["CHS60.3x3.2", 5.74],
    ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33],
    ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67],
    ["CHS88.9x5", 13.18], ["CHS114.3x4", 13.86],
    ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS168.3x5", 25.65], ["CHS168.3x6.3", 32.06],
    ["CHS193.7x6.3", 37.09], ["CHS193.7x8", 46.67],
    ["CHS219.1x8", 53.06], ["CHS244.5x8", 59.44],
    ["CHS273x10", 82.62], ["CHS323.9x10", 98.61],
    ["CHS355.6x12.5", 134.74], ["CHS406.4x12.5", 154.68],
    ["CHS457x16", 221.67]
  ];
  const specs = sections.map(s => "AL7075 " + s[0]);
  const areas = sections.map(s => s[1]);
  const sectionIndex = spec => specs.indexOf(spec);

  const note =
    "Pinned, maximum-depth twin Pratt trusses use AL7075 tubes; one plan-bracing plane is removed only if conservative analysis gates pass, then member sizes are minimized.";

  const nodes = [];
  const items = [];
  const active = [];
  const groups = {
    top: [], bottom: [], web: [], vertical: [],
    topTie: [], bottomTie: [], cross: [],
    topPlan: [], bottomPlan: []
  };

  const initial = {
    top: 19, bottom: 16, web: 14, vertical: 12,
    topTie: 12, bottomTie: 12, cross: 14,
    topPlan: 14, bottomPlan: 14
  };

  for (let i = 0; i < xs.length; i++) {
    nodes.push({ id: `BL${i}`, x: xs[i], y: -3.35, z: -2.65 });
    nodes.push({ id: `BR${i}`, x: xs[i], y: -3.35, z: 2.65 });
  }

  function add(a, b, role) {
    const k = items.length;
    items.push({ a, b, spec: specs[initial[role]] });
    active.push(true);
    groups[role].push(k);
  }

  for (let i = 0; i < 6; i++) {
    add(`L${i}`, `L${i + 1}`, "top");
    add(`R${i}`, `R${i + 1}`, "top");
    add(`BL${i}`, `BL${i + 1}`, "bottom");
    add(`BR${i}`, `BR${i + 1}`, "bottom");

    if (i < 3) {
      add(`L${i}`, `BL${i + 1}`, "web");
      add(`R${i}`, `BR${i + 1}`, "web");
    } else {
      add(`BL${i}`, `L${i + 1}`, "web");
      add(`BR${i}`, `R${i + 1}`, "web");
    }

    add(`L${i}`, `R${i + 1}`, "topPlan");
    add(`BL${i}`, `BR${i + 1}`, "bottomPlan");
  }

  for (let i = 0; i < 7; i++) {
    add(`L${i}`, `BL${i}`, "vertical");
    add(`R${i}`, `BR${i}`, "vertical");
    add(`L${i}`, `R${i}`, "topTie");
    add(`BL${i}`, `BR${i}`, "bottomTie");

    if (i % 2 === 0) add(`L${i}`, `BR${i}`, "cross");
    else add(`R${i}`, `BL${i}`, "cross");
  }

  const base = { nodes, items, active };
  const maxCalls = 360;
  let calls = 0;

  function cloneState(s) {
    return {
      nodes: s.nodes,
      items: s.items.map(m => ({ a: m.a, b: m.b, spec: m.spec })),
      active: s.active.slice()
    };
  }

  function publicDesign(s) {
    return {
      note,
      nodes: s.nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z })),
      members: s.items
        .filter((m, k) => s.active[k])
        .map(m => ({ a: m.a, b: m.b, spec: m.spec }))
    };
  }

  function run(s) {
    if (calls >= maxCalls) return null;
    calls++;
    try {
      return analyse(publicDesign(s));
    } catch (e) {
      return { ok: false, error: String(e) };
    }
  }

  function numberOr(x, fallback) {
    const n = Number(x);
    return Number.isFinite(n) ? n : fallback;
  }

  // Keep meaningful margin for unit-to-unit material variation and
  // the unsampled positions within the published load ranges.
  function safe(r) {
    if (!r || r.error || r.ok !== true) return false;
    if (numberOr(r.maxUtil, Infinity) > 0.70) return false;
    if (numberOr(r.fatigueWorst, Infinity) > 0.80) return false;

    const alpha = numberOr(r.alphaCrMin, numberOr(r.alphaCr, 0));
    if (alpha < 8) return false;
    if (numberOr(r.frequency, 0) < 3.2) return false;

    const sagLimit = numberOr(r.sagLimit, 52.3);
    const swayLimit = numberOr(r.swayLimit, 69.7);
    if (numberOr(r.sag, Infinity) > 0.80 * sagLimit) return false;
    if (numberOr(r.sway, Infinity) > 0.80 * swayLimit) return false;

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        r.robustness.ok === false) return false;
    return true;
  }

  let best = base;
  let report = run(best);
  if (!safe(report)) return publicDesign(best);

  // Retain one complete horizontal bracing plane if the other can be
  // removed without losing the prescribed stability and margin.
  for (const role of ["topPlan", "bottomPlan"]) {
    const candidate = cloneState(best);
    for (const k of groups[role]) candidate.active[k] = false;
    const r = run(candidate);
    if (safe(r)) {
      best = candidate;
      report = r;
      break;
    }
  }

  // Find a light common size for each structural role before individual sizing.
  const roleOrder = [
    "top", "bottom", "web", "vertical",
    "topTie", "bottomTie", "cross", "bottomPlan", "topPlan"
  ];

  for (const role of roleOrder) {
    const ids = groups[role].filter(k => best.active[k]);
    if (!ids.length || calls >= maxCalls) continue;

    const original = sectionIndex(best.items[ids[0]].spec);
    if (original <= 0) continue;

    let low = -1;
    let high = original; // known safe
    while (high - low > 1 && calls < maxCalls) {
      const mid = Math.floor((low + high) / 2);
      const candidate = cloneState(best);
      for (const k of ids) candidate.items[k].spec = specs[mid];

      const r = run(candidate);
      if (!r) break;
      if (safe(r)) {
        best = candidate;
        report = r;
        high = mid;
      } else {
        low = mid;
      }
    }
  }

  const point = Object.create(null);
  for (const n of nodes) point[n.id] = [n.x, n.y, n.z];
  for (let i = 0; i < xs.length; i++) {
    point[`L${i}`] = [xs[i], 0, -2.65];
    point[`R${i}`] = [xs[i], 0, 2.65];
  }

  function memberLength(m) {
    const p = point[m.a], q = point[m.b];
    if (!p || !q) return 1;
    return Math.hypot(p[0] - q[0], p[1] - q[1], p[2] - q[2]);
  }

  function memberUtil(r, item) {
    if (!r || !Array.isArray(r.members)) return 0;
    const id1 = item.a + "-" + item.b;
    const id2 = item.b + "-" + item.a;
    for (const m of r.members) {
      if (m && (m.id === id1 || m.id === id2))
        return numberOr(m.util, 0);
    }
    return 0;
  }

  // Prioritize low-utilization, high-mass members for individual reductions.
  const order = best.items
    .map((m, k) => {
      if (!best.active[k]) return null;
      const idx = sectionIndex(m.spec);
      if (idx <= 0) return null;
      const len = memberLength(m);
      const areaSaving = areas[idx] - areas[idx - 1];
      const massSaving = areaSaving * 0.0001 * 2700 * len *
        (1 + 0.7 / Math.max(0.4, len));
      const u = memberUtil(report, m);
      return { k, priority: massSaving / (0.15 + Math.max(0, u)) };
    })
    .filter(Boolean)
    .sort((a, b) => b.priority - a.priority);

  // Binary-search the lightest safe size for each member.
  for (const entry of order) {
    if (calls >= maxCalls) break;
    const k = entry.k;
    const original = sectionIndex(best.items[k].spec);
    if (original <= 0) continue;

    let low = -1;
    let high = original;
    while (high - low > 1 && calls < maxCalls) {
      const mid = Math.floor((low + high) / 2);
      const candidate = cloneState(best);
      candidate.items[k].spec = specs[mid];

      const r = run(candidate);
      if (!r) break;
      if (safe(r)) {
        best = candidate;
        report = r;
        high = mid;
      } else {
        low = mid;
      }
    }
  }

  // A final adjacent-size pass can capture reductions made possible by
  // load redistribution during the member-by-member search.
  for (const entry of order) {
    if (calls >= maxCalls) break;
    const k = entry.k;
    const idx = sectionIndex(best.items[k].spec);
    if (idx <= 0) continue;

    const candidate = cloneState(best);
    candidate.items[k].spec = specs[idx - 1];
    const r = run(candidate);
    if (safe(r)) {
      best = candidate;
      report = r;
    }
  }

  return publicDesign(best);
}

function design(site, analyse) {
  const xs = [0, 3.483, 6.967, 10.45, 13.933, 17.417, 20.9];

  const sectionData = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94],
    ["CHS48.3x3.2", 4.53], ["CHS60.3x3.2", 5.74],
    ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33],
    ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67],
    ["CHS88.9x5", 13.18], ["CHS114.3x4", 13.86],
    ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS168.3x5", 25.65], ["CHS168.3x6.3", 32.06],
    ["CHS193.7x6.3", 37.09], ["CHS193.7x8", 46.67],
    ["CHS219.1x8", 53.06], ["CHS244.5x8", 59.44],
    ["CHS273x10", 82.62], ["CHS323.9x10", 98.61],
    ["CHS355.6x12.5", 134.74], ["CHS406.4x12.5", 154.68],
    ["CHS457x16", 221.67]
  ];
  const specs = sectionData.map(s => "AL7075 " + s[0]);
  const areas = sectionData.map(s => s[1]);
  const sectionIndex = spec => specs.indexOf(spec);

  const note =
    "A maximum-depth pinned AL7075 twin-Pratt box is sized against conservative unit-variation margins, while analysis prunes redundant bracing only when stability remains adequate.";

  const nodes = [];
  const items = [];
  const active = [];
  const groups = {
    top: [], bottom: [], web: [], vertical: [],
    topTie: [], bottomTie: [], cross: [],
    topPlan: [], bottomPlan: []
  };

  const initial = {
    top: 19, bottom: 16, web: 14, vertical: 16,
    topTie: 12, bottomTie: 12, cross: 14,
    topPlan: 14, bottomPlan: 14
  };

  for (let i = 0; i < xs.length; i++) {
    nodes.push({ id: `BL${i}`, x: xs[i], y: -3.37, z: -2.65 });
    nodes.push({ id: `BR${i}`, x: xs[i], y: -3.37, z: 2.65 });
  }

  function add(a, b, role) {
    const k = items.length;
    items.push({
      a, b, role,
      spec: specs[initial[role]]
    });
    active.push(true);
    groups[role].push(k);
  }

  for (let i = 0; i < 6; i++) {
    add(`L${i}`, `L${i + 1}`, "top");
    add(`R${i}`, `R${i + 1}`, "top");
    add(`BL${i}`, `BL${i + 1}`, "bottom");
    add(`BR${i}`, `BR${i + 1}`, "bottom");

    if (i < 3) {
      add(`L${i}`, `BL${i + 1}`, "web");
      add(`R${i}`, `BR${i + 1}`, "web");
    } else {
      add(`BL${i}`, `L${i + 1}`, "web");
      add(`BR${i}`, `R${i + 1}`, "web");
    }

    add(`L${i}`, `R${i + 1}`, "topPlan");
    add(`BL${i}`, `BR${i + 1}`, "bottomPlan");
  }

  for (let i = 0; i < 7; i++) {
    add(`L${i}`, `BL${i}`, "vertical");
    add(`R${i}`, `BR${i}`, "vertical");
    add(`L${i}`, `R${i}`, "topTie");
    add(`BL${i}`, `BR${i}`, "bottomTie");

    if (i % 2 === 0) add(`L${i}`, `BR${i}`, "cross");
    else add(`R${i}`, `BL${i}`, "cross");
  }

  const maxCalls = 380;
  let calls = 0;

  function cloneState(s) {
    return {
      nodes: s.nodes,
      items: s.items.map(m => ({
        a: m.a, b: m.b, role: m.role, spec: m.spec
      })),
      active: s.active.slice()
    };
  }

  function publicDesign(s) {
    return {
      note,
      nodes: s.nodes.map(n => ({
        id: n.id, x: n.x, y: n.y, z: n.z
      })),
      members: s.items
        .filter((m, k) => s.active[k])
        .map(m => ({ a: m.a, b: m.b, spec: m.spec }))
    };
  }

  function num(value, fallback) {
    if (value === undefined || value === null || value === "") return fallback;
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
  }

  function run(s) {
    if (calls >= maxCalls) return null;
    calls++;
    try {
      return analyse(publicDesign(s));
    } catch (e) {
      return { error: String(e) };
    }
  }

  function memberUtil(report, item) {
    if (!report || !Array.isArray(report.members)) return 0;
    const id1 = item.a + "-" + item.b;
    const id2 = item.b + "-" + item.a;
    for (const m of report.members) {
      if (m && (m.id === id1 || m.id === id2))
        return num(m.util, 0);
    }
    return 0;
  }

  function safe(r) {
    if (!r || r.error) return false;

    if (num(r.maxUtil, Infinity) > 0.58) return false;
    if (num(r.fatigueWorst, Infinity) > 0.78) return false;

    const alpha = num(r.alphaCrMin, num(r.alphaCr, 0));
    if (alpha < 8) return false;

    const frequency = num(r.frequency, num(r.fMin, 0));
    if (frequency < 3.15) return false;

    const sagLimit = num(r.sagLimit, 52.3);
    const swayLimit = num(r.swayLimit, 69.7);
    if (num(r.sag, Infinity) > 0.82 * sagLimit) return false;
    if (num(r.sway, Infinity) > 0.82 * swayLimit) return false;

    if (Array.isArray(r.members)) {
      for (const m of r.members) {
        const mode = String(m && m.mode ? m.mode : "").toLowerCase();
        const u = num(m && m.util, 0);
        if (
          (mode.includes("buck") ||
           mode.includes("compress") ||
           mode.includes("instab")) &&
          u > 0.50
        ) return false;
      }
    }

    // All selected members are CHS tubes, so there are no wire-rope or
    // solid-rod snap cases to check.
    return true;
  }

  let best = { nodes, items, active };
  let report = run(best);

  // If a conservative gate is missed, enlarge the currently most utilized
  // members before attempting any reductions.
  for (let iteration = 0;
       !safe(report) && iteration < 16 && calls < maxCalls;
       iteration++) {
    if (!report || report.error) break;

    const order = best.items
      .map((m, k) => ({
        k,
        util: best.active[k] ? memberUtil(report, m) : -1
      }))
      .filter(e => e.util >= 0)
      .sort((a, b) => b.util - a.util);

    const candidate = cloneState(best);
    let changed = false;

    for (const entry of order.slice(0, 6)) {
      const idx = sectionIndex(candidate.items[entry.k].spec);
      if (idx >= 0 && idx < specs.length - 1) {
        candidate.items[entry.k].spec = specs[idx + 1];
        changed = true;
      }
    }

    if (!changed) {
      for (const role of [
        "vertical", "top", "web", "bottom", "cross",
        "topPlan", "bottomPlan", "topTie", "bottomTie"
      ]) {
        let roleChanged = false;
        for (const k of groups[role]) {
          if (!candidate.active[k]) continue;
          const idx = sectionIndex(candidate.items[k].spec);
          if (idx >= 0 && idx < specs.length - 1) {
            candidate.items[k].spec = specs[idx + 1];
            roleChanged = true;
          }
        }
        if (roleChanged) {
          changed = true;
          break;
        }
      }
    }

    if (!changed) break;
    const next = run(candidate);
    if (!next) break;
    best = candidate;
    report = next;
  }

  if (!safe(report)) return publicDesign(best);

  const seed = cloneState(best);
  let bestMass = num(report.mass, Infinity);

  function testVariant(dropRoles, keepCross) {
    if (calls >= maxCalls) return null;

    const candidate = cloneState(seed);
    for (const role of dropRoles) {
      for (const k of groups[role]) candidate.active[k] = false;
    }

    if (Array.isArray(keepCross)) {
      const keep = new Set(keepCross);
      groups.cross.forEach((k, j) => {
        candidate.active[k] = keep.has(j);
      });
    }

    const r = run(candidate);
    if (!safe(r)) return { safe: false };

    const mass = num(r.mass, Infinity);
    if (mass < bestMass) {
      best = candidate;
      report = r;
      bestMass = mass;
    }
    return { safe: true, mass };
  }

  let allCrossRemovalSafe = false;
  const dropSets = [
    ["bottomPlan"],
    ["topPlan"],
    ["bottomPlan", "topPlan"],
    ["cross"],
    ["bottomPlan", "cross"],
    ["topPlan", "cross"],
    ["bottomPlan", "topPlan", "cross"]
  ];

  for (const drop of dropSets) {
    if (calls >= maxCalls) break;
    const result = testVariant(drop, null);
    if (drop.length === 1 && drop[0] === "cross")
      allCrossRemovalSafe = !!(result && result.safe);
  }

  // If every cross-frame brace is needed for stability, test sparse layouts.
  if (!allCrossRemovalSafe) {
    for (let j = 0; j < 7 && calls < maxCalls; j++)
      testVariant([], [j]);
    for (let j = 0; j < 7 && calls < maxCalls; j++)
      testVariant(["bottomPlan"], [j]);
  }

  function memberLength(m) {
    const point = Object.create(null);
    for (const n of nodes) point[n.id] = [n.x, n.y, n.z];
    for (let i = 0; i < xs.length; i++) {
      point[`L${i}`] = [xs[i], 0, -2.65];
      point[`R${i}`] = [xs[i], 0, 2.65];
    }
    const p = point[m.a], q = point[m.b];
    if (!p || !q) return 1;
    return Math.hypot(p[0] - q[0], p[1] - q[1], p[2] - q[2]);
  }

  const roleOrder = [
    "top", "bottom", "vertical", "web",
    "topTie", "bottomTie", "topPlan", "bottomPlan", "cross"
  ];

  // Find a safe common section size for each active structural role.
  for (const role of roleOrder) {
    if (calls >= maxCalls) break;
    const ids = groups[role].filter(k => best.active[k]);
    if (!ids.length) continue;

    const indices = ids.map(k => sectionIndex(best.items[k].spec));
    const highStart = Math.min(...indices);
    if (highStart <= 0 || indices.some(i => i !== highStart)) continue;

    let low = -1;
    let high = highStart;
    while (high - low > 1 && calls < maxCalls) {
      const mid = Math.floor((low + high) / 2);
      const candidate = cloneState(best);
      for (const k of ids) candidate.items[k].spec = specs[mid];

      const r = run(candidate);
      if (!r) break;
      if (safe(r)) {
        best = candidate;
        report = r;
        high = mid;
      } else {
        low = mid;
      }
    }
  }

  // Then independently minimize members, prioritizing larger mass savings.
  const order = best.items
    .map((m, k) => {
      if (!best.active[k]) return null;
      const idx = sectionIndex(m.spec);
      if (idx <= 0) return null;

      const length = memberLength(m);
      const saving =
        0.281 * (areas[idx] - areas[idx - 1]) * (length + 0.7);
      const u = Math.max(0, memberUtil(report, m));
      return { k, priority: saving / (0.15 + u) };
    })
    .filter(Boolean)
    .sort((a, b) => b.priority - a.priority);

  for (const entry of order) {
    if (calls >= maxCalls) break;
    const k = entry.k;
    const start = sectionIndex(best.items[k].spec);
    if (start <= 0) continue;

    let low = -1;
