    let high = sectionIndex(best.items[k].spec);
    if (high <= 0) continue;
    let low = -1;

    while (high - low > 1 && calls < maxCalls) {
      const mid = Math.floor((low + high) / 2);
      const candidate = cloneState(best);
      candidate.items[k].spec = sizedSpec(candidate.items[k].spec, mid);

      const r = run(candidate);
      if (safe(r)) {
        best = candidate;
        report = r;
        bestMass = massOf(r);
        high = mid;
      } else {
        low = mid;
      }
    }
