      candidate.items[k].spec = sizedSpec(candidate.items[k].spec, idx - 1);
      const r = run(candidate);
      if (safe(r) && massOf(r) < bestMass) {
        best = candidate;
        report = r;
        bestMass = massOf(r);
        changed = true;
      }
    }
    if (!changed) break;
  }

