    if (!Number.isFinite(sag) && Array.isArray(r && r.cases)) {
      for (const c of r.cases) {
        const v = number(c && c.sag);
        if (Number.isFinite(v)) {
          sag = Number.isFinite(sag) ? Math.max(sag, v) : v;
          observed = true;
        }
      }
