    const idx = sectionIndex(best.items[k].spec);
    if (idx < 0) continue;
    const saving = 110 * areas[idx] * 1e-4 * (lengthOf(best.items[k]) + 0.7);
    const u0 = memberUtil(bestReport, best.items[k]);
    const u = Number.isFinite(u0) ? Math.max(0, u0) : 0.12;
    alloyCandidates.push({ k, priority: saving / (0.18 + u) });
  }
  alloyCandidates.sort((a, b) => b.priority - a.priority);

  let alloyTries = 0;
  for (const e of alloyCandidates) {
    if (calls >= maxCalls - 12 || alloyTries >= 35) break;
    const k = e.k;
    if (materialOf(best.items[k].spec) !== "AL7075") continue;
    const candidate = cloneState(best);
    candidate.items[k].spec =
      candidate.items[k].spec.replace(/^AL7075 /, "AL6082 ");
    consider(candidate);
    alloyTries++;
  }

  // Spend remaining calls refining members with a sizeable unresolved interval.
  for (let pass = 0; pass < 2 && calls < maxCalls - 12; pass++) {
    for (const entry of order) {
      if (calls >= maxCalls - 12) break;
      const k = entry.k;
      if (!best.active[k]) continue;

      const high = sectionIndex(best.items[k].spec);
      const low = Number.isFinite(lowerBounds[k]) ? lowerBounds[k] : -1;
      if (high <= 0 || high - low <= 1) continue;

      const mid = Math.floor((high + low) / 2);
      const candidate = cloneState(best);
      candidate.items[k].spec = sizedSpec(candidate.items[k].spec, mid);
      const r = run(candidate);

      if (safe(r)) {
        const mass = massOf(r, candidate);
        if (mass < bestMass + 1e-7) {
          best = candidate;
          bestReport = r;
          bestMass = mass;
        }
      } else {
        lowerBounds[k] = mid;
      }
    }
  }

  // Recheck a few brace deletions after tube sizing.
