  for (const e of braceEntries(best)) {
    if (calls >= maxCalls || finalBraceTries >= 12) break;
    if (!best.active[e.k]) continue;
    const candidate = cloneState(best);
    candidate.active[e.k] = false;
    consider(candidate);
    finalBraceTries++;
  }

  return publicDesign(best);
}

