        if (mode.includes("fatigue") && u > 0.70) return false;
        if ((mode.includes("buck") || mode.includes("compress") ||
             mode.includes("instab")) && u > 0.50) return false;
        if (!mode.includes("fatigue") && !mode.includes("buck") &&
            !mode.includes("compress") && !mode.includes("instab") &&
            u > 0.52) return false;
      }
    }
    return true;
  }

  function massOf(r, s) {
    const reported = number(r && r.mass);
    if (Number.isFinite(reported)) return reported;

    let mass = 12 * (s.nodes.length + 14);
    for (let k = 0; k < s.items.length; k++) {
      if (!s.active[k]) continue;
      const m = s.items[k];
      const idx = sectionIndex(m.spec);
      if (idx < 0) continue;
      const rho = materialOf(m.spec) === "AL6082" ? 2700 : 2810;
      const kgPerM = areas[idx] * 1e-4 * rho;
      mass += kgPerM * (lengthOf(m) + 0.7);
    }
    return mass;
  }

  let best = {
    nodes, items, active: items.map(() => true)
  };
  let bestReport = run(best);
  if (!safe(bestReport)) return publicDesign(best);
  let bestMass = massOf(bestReport, best);

  function consider(candidate, report) {
    const r = report || run(candidate);
    if (!safe(r)) return false;
    const mass = massOf(r, candidate);
    if (mass < bestMass - 1e-7) {
      best = candidate;
      bestReport = r;
      bestMass = mass;
    }
    return true;
  }

  function tryRoleSize(role, idx) {
    const candidate = cloneState(best);
    for (const k of groups[role]) {
      if (candidate.active[k])
        candidate.items[k].spec = sizedSpec(candidate.items[k].spec, idx);
    }
    const r = run(candidate);
    return consider(candidate, r);
  }

  // Coordinate descent on complete member roles, followed by a second pass.
  for (let pass = 0; pass < 2; pass++) {
    for (const role of roleNames) {
      if (calls >= maxCalls - 65) break;
      const ids = groups[role].filter(k => best.active[k]);
      if (!ids.length) continue;

      let high = Math.min(...ids.map(k => sectionIndex(best.items[k].spec)));
      let low = -1;
      while (high - low > 1 && calls < maxCalls - 65) {
        const mid = Math.floor((high + low) / 2);
        if (tryRoleSize(role, mid)) high = mid;
        else low = mid;
      }
    }
  }

  function tryDropRole(role) {
    const ids = groups[role].filter(k => best.active[k]);
    if (!ids.length || calls >= maxCalls - 50) return;
    const candidate = cloneState(best);
    for (const k of ids) candidate.active[k] = false;
    consider(candidate);
  }

  for (const role of ["topPlan", "bottomPlan", "cross"])
    tryDropRole(role);

  function memberInfo(r, item) {
    if (!r || !Array.isArray(r.members)) return { util: NaN, mode: "" };
    const id1 = item.a + "-" + item.b;
    const id2 = item.b + "-" + item.a;
    let util = NaN, mode = "";
    for (const m of r.members) {
      if (!m || (m.id !== id1 && m.id !== id2)) continue;
      const u = number(m.util);
      if (Number.isFinite(u) && (!Number.isFinite(util) || u > util)) {
        util = u;
        mode = String(m.mode || "").toLowerCase();
      }
    }
    return { util, mode };
  }

  function memberOrder() {
    const out = [];
    for (let k = 0; k < best.items.length; k++) {
      if (!best.active[k]) continue;
      const m = best.items[k];
      const idx = sectionIndex(m.spec);
      if (idx <= 0) continue;
      let u = memberInfo(bestReport, m).util;
      if (!Number.isFinite(u)) u = 0.25;
      const rho = materialOf(m.spec) === "AL6082" ? 2700 : 2810;
      const saving = Math.max(0, areas[idx] - areas[0]) * 1e-4 *
        rho * (lengthOf(m) + 0.7);
      out.push({ k, priority: saving / (0.12 + Math.max(0, u)) });
    }
    out.sort((a, b) => b.priority - a.priority);
    return out;
  }

  function refineMember(k) {
    let u = memberInfo(bestReport, best.items[k]).util;
    if (!Number.isFinite(u)) u = 0.25;
    let gap = u < 0.12 ? 8 : u < 0.25 ? 5 : u < 0.38 ? 3 : u < 0.52 ? 2 : 1;

    for (let attempt = 0; attempt < 3; attempt++) {
      if (calls >= maxCalls - 50 || !best.active[k]) break;
      const idx = sectionIndex(best.items[k].spec);
      if (idx <= 0) break;
      const target = Math.max(0, idx - gap);
      if (target >= idx) break;

      const candidate = cloneState(best);
      candidate.items[k].spec = sizedSpec(candidate.items[k].spec, target);
      const r = run(candidate);
      if (safe(r)) {
        const mass = massOf(r, candidate);
        if (mass < bestMass - 1e-7) {
          best = candidate;
          bestReport = r;
          bestMass = mass;
        }
      } else if (gap === 1) {
        break;
      }
      gap = Math.max(1, Math.ceil(gap / 2));
    }
  }

  for (const entry of memberOrder()) {
    if (calls >= maxCalls - 50) break;
    refineMember(entry.k);
  }

  // Remove individual braces only when the complete analysis remains safe.
  const braceRoles = ["topPlan", "bottomPlan", "cross", "topTie", "bottomTie"];
  const braces = [];
  for (const role of braceRoles) {
    for (const k of groups[role]) {
      if (!best.active[k]) continue;
      const idx = sectionIndex(best.items[k].spec);
      if (idx < 0) continue;
      const rho = materialOf(best.items[k].spec) === "AL6082" ? 2700 : 2810;
      braces.push({
        k,
        saving: areas[idx] * 1e-4 * rho * (lengthOf(best.items[k]) + 0.7)
      });
    }
  }
  braces.sort((a, b) => b.saving - a.saving);
  let braceTries = 0;
  for (const e of braces) {
    if (calls >= maxCalls - 30 || braceTries >= 18) break;
    if (!best.active[e.k]) continue;
    const candidate = cloneState(best);
    candidate.active[e.k] = false;
    consider(candidate);
    braceTries++;
  }

  // Try 6082 only member-by-member; retain it only if the conservative gates pass.
  const alloyCandidates = [];
  for (let k = 0; k < best.items.length; k++) {
    if (!best.active[k] ||
        materialOf(best.items[k].spec) !== "AL7075") continue;
    const idx = sectionIndex(best.items[k].spec);
    if (idx < 0) continue;
    let u = memberInfo(bestReport, best.items[k]).util;
    if (!Number.isFinite(u)) u = 0.25;
    const saving = 110 * areas[idx] * 1e-4 * (lengthOf(best.items[k]) + 0.7);
    alloyCandidates.push({ k, priority: saving / (0.12 + Math.max(0, u)) });
  }
  alloyCandidates.sort((a, b) => b.priority - a.priority);

  let alloyTries = 0;
  for (const e of alloyCandidates) {
    if (calls >= maxCalls || alloyTries >= 30) break;
    const k = e.k;
    if (!best.active[k] ||
        materialOf(best.items[k].spec) !== "AL7075") continue;
    const candidate = cloneState(best);
    candidate.items[k].spec =
      candidate.items[k].spec.replace(/^AL7075 /, "AL6082 ");
    consider(candidate);
    alloyTries++;
  }

  return publicDesign(best);
}

function design(site, analyse) {
  const Lx = [0, 3.483, 6.967, 10.45, 13.933, 17.417, 20.9];
  const L = 20.9;
  const hmax = 3.3;
  const By = {};
  for (let i = 1; i <= 5; i++) {
    const x = Lx[i];
    const h = hmax * 4 * (x / L) * (1 - x / L);
    By[i] = -h;
  }

  function makeDesign(specs) {
    const nodes = [];
    for (let i = 1; i <= 5; i++) {
      nodes.push({
        id: "B" + i,
        x: Lx[i],
        y: +By[i].toFixed(6),
        z: 0,
        joint: "pin"
      });
    }

    const defs = [];
    const add = (a, b, g) => defs.push([a, b, g]);

    // top chords along both deck edges
    for (let i = 0; i <= 5; i++) {
      add("L" + i, "L" + (i + 1), "top");
      add("R" + i, "R" + (i + 1), "top");
    }

    // top transverse deck-plane ties
    for (let i = 0; i <= 6; i++) {
      add("L" + i, "R" + i, "cross");
    }

    // central sagging bottom chord
    for (let i = 1; i <= 4; i++) {
      add("B" + i, "B" + (i + 1), "bottomCentral");
    }

    // Y-shaped anchor links at both ends
    add("L0", "B1", "endLinks");
    add("R0", "B1", "endLinks");
    add("L6", "B5", "endLinks");
    add("R6", "B5", "endLinks");

    // central-bottom V struts at interior deck stations
    for (let i = 1; i <= 5; i++) {
      add("L" + i, "B" + i, "strut");
      add("R" + i, "B" + i, "strut");
    }

    // side-plane X bracing in interior panels
    for (let i = 1; i <= 4; i++) {
      add("L" + i, "B" + (i + 1), "sideDiag");
      add("L" + (i + 1), "B" + i, "sideDiag");
      add("R" + i, "B" + (i + 1), "sideDiag");
      add("R" + (i + 1), "B" + i, "sideDiag");
    }

    // top-plane X bracing in every bay
    for (let i = 0; i <= 5; i++) {
      add("L" + i, "R" + (i + 1), "topDiag");
      add("R" + i, "L" + (i + 1), "topDiag");
    }

    const members = defs.map(d => [d[0], d[1], specs[d[2]]]);
    return {
      note: "Triangular under-deck tied truss with a central sagging chord and X-braced top and side planes.",
      nodes: nodes,
      members: members
    };
  }

  const groups = ["top", "bottomCentral", "endLinks", "strut", "cross", "sideDiag", "topDiag"];
  const heavy = "AL7075 CHS457x16";

  const cand = {
    top: [
      "AL7075 CHS139.7x5",
      "AL7075 CHS168.3x6.3",
      "AL7075 CHS193.7x6.3",
      "AL7075 CHS219.1x8",
      "AL7075 CHS244.5x8",
      "AL7075 CHS273x10",
      "AL7075 CHS323.9x10",
      "AL7075 CHS355.6x12.5",
      "AL7075 CHS457x16"
    ],
    bottomCentral: [
      "AL7075 CHS168.3x6.3",
      "AL7075 CHS193.7x8",
      "AL7075 CHS219.1x8",
      "AL7075 CHS244.5x8",
      "AL7075 CHS273x10",
      "AL7075 CHS323.9x10",
      "AL7075 CHS355.6x12.5",
      "AL7075 CHS457x16"
    ],
    endLinks: [
      "AL7075 CHS139.7x5",
      "AL7075 CHS168.3x6.3",
      "AL7075 CHS193.7x8",
      "AL7075 CHS219.1x8",
      "AL7075 CHS244.5x8",
      "AL7075 CHS273x10",
      "AL7075 CHS323.9x10",
      "AL7075 CHS355.6x12.5",
      "AL7075 CHS457x16"
    ],
    strut: [
      "AL7075 CHS88.9x5",
      "AL7075 CHS114.3x5",
      "AL7075 CHS139.7x5",
      "AL7075 CHS168.3x6.3",
      "AL7075 CHS193.7x6.3",
      "AL7075 CHS219.1x8",
      "AL7075 CHS244.5x8",
      "AL7075 CHS273x10",
      "AL7075 CHS355.6x12.5",
      "AL7075 CHS457x16"
    ],
    cross: [
      "AL7075 CHS88.9x5",
      "AL7075 CHS114.3x5",
      "AL7075 CHS139.7x5",
      "AL7075 CHS168.3x6.3",
      "AL7075 CHS193.7x6.3",
      "AL7075 CHS219.1x8",
      "AL7075 CHS244.5x8",
      "AL7075 CHS273x10",
      "AL7075 CHS355.6x12.5",
      "AL7075 CHS457x16"
    ],
    sideDiag: [
      "AL7075 CHS88.9x5",
      "AL7075 CHS114.3x5",
      "AL7075 CHS139.7x5",
      "AL7075 CHS168.3x6.3",
      "AL7075 CHS193.7x6.3",
      "AL7075 CHS219.1x8",
      "AL7075 CHS244.5x8",
      "AL7075 CHS273x10",
      "AL7075 CHS355.6x12.5",
      "AL7075 CHS457x16"
    ],
    topDiag: [
      "AL7075 CHS60.3x4",
      "AL7075 CHS76.1x4",
      "AL7075 CHS88.9x5",
      "AL7075 CHS114.3x5",
      "AL7075 CHS139.7x5",
      "AL7075 CHS168.3x6.3",
      "AL7075 CHS193.7x6.3",
      "AL7075 CHS219.1x8",
      "AL7075 CHS244.5x8",
      "AL7075 CHS273x10",
      "AL7075 CHS355.6x12.5",
      "AL7075 CHS457x16"
    ]
  };

  let calls = 0;
  function test(des) {
    if (calls >= 398) return null;
    calls++;
    return analyse(des);
  }

  function strict(r) {
    if (!r || r.error || !r.ok) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > 0.60) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < 8.0) return false;
    if (typeof r.frequency === "number" && r.frequency < 3.20) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.80 * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > 0.80 * r.swayLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > 0.70) return false;
    if (r.robustness === false) return false;
    return true;
  }

  function acceptable(r) {
    if (!r || r.error || !r.ok) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > 0.90) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < 5.5) return false;
    if (typeof r.frequency === "number" && r.frequency < 2.98) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.95 * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > 0.95 * r.swayLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > 0.92) return false;
    if (r.robustness === false) return false;
    return true;
  }

  let specs = {};
  for (const g of groups) specs[g] = heavy;
  let curDes = makeDesign(specs);
  let curRes = test(curDes);

  let bestStrict = null;
  let bestAcc = null;

  function record(r, sp) {
    if (!r || r.error || !r.ok) return;
    if (acceptable(r)) {
      if (!bestAcc || r.mass < bestAcc.mass) {
        bestAcc = { mass: r.mass, specs: Object.assign({}, sp), res: r };
      }
    }
    if (strict(r)) {
      if (!bestStrict || r.mass < bestStrict.mass) {
        bestStrict = { mass: r.mass, specs: Object.assign({}, sp), res: r };
      }
    }
  }

  record(curRes, specs);

  if (!curRes || !curRes.ok) {
    const fallbackSpecs = [
      "S460 CHS355.6x12.5",
      "S690 CHS355.6x12.5",
      "S460 CHS406.4x12.5",
      "S690 CHS406.4x12.5",
      "S460 CHS457x16",
      "S690 CHS457x16"
    ];
    for (const spec of fallbackSpecs) {
      let s = {};
      for (const g of groups) s[g] = spec;
      let r = test(makeDesign(s));
      if (r && r.ok) {
        specs = s;
        curRes = r;
        record(r, s);
        if (strict(r)) break;
      }
    }
  }

  for (let pass = 0; pass < 3 && calls < 370; pass++) {
    let changed = false;
    for (const g of groups) {
      if (calls >= 370) break;
      let chosen = null;
      let chosenRes = null;

      for (const c of cand[g]) {
        let trialSpecs = Object.assign({}, specs);
        trialSpecs[g] = c;
        let r = test(makeDesign(trialSpecs));

        if (r && acceptable(r)) record(r, trialSpecs);

        if (r && strict(r)) {
          chosen = c;
          chosenRes = r;
          record(r, trialSpecs);
          break;
        }
        if (!r && calls >= 370) break;
      }

      if (chosen !== null && chosen !== specs[g]) {
        specs[g] = chosen;
        curRes = chosenRes;
        changed = true;
      }
    }
    if (!changed) break;
  }

  if (curRes && acceptable(curRes)) record(curRes, specs);

  let finalSpecs;
  if (bestStrict) {
    finalSpecs = bestStrict.specs;
  } else if (bestAcc) {
    finalSpecs = bestAcc.specs;
  } else {
    finalSpecs = {};
    for (const g of groups) finalSpecs[g] = heavy;
  }

  let finalDes = makeDesign(finalSpecs);
  let finalRes = test(finalDes);

  if (!finalRes || !finalRes.ok || !acceptable(finalRes)) {
    if (bestAcc && bestAcc.specs) {
      let d2 = makeDesign(bestAcc.specs);
      let r2 = test(d2);
      if (r2 && r2.ok && acceptable(r2)) {
        finalDes = d2;
        finalRes = r2;
      }
    }
  }

  if (!finalRes || !finalRes.ok || !acceptable(finalRes)) {
    const fallbackSpecs = [
      "AL7075 CHS457x16",
      "S460 CHS355.6x12.5",
      "S690 CHS355.6x12.5",
      "S460 CHS406.4x12.5",
      "S690 CHS406.4x12.5",
      "S460 CHS457x16",
      "S690 CHS457x16"
    ];
    for (const spec of fallbackSpecs) {
      let s = {};
      for (const g of groups) s[g] = spec;
      let d = makeDesign(s);
      let r = test(d);
      if (r && r.ok) {
        finalDes = d;
        finalRes = r;
        if (acceptable(r)) break;
      }
    }
  }

  finalDes.note = "Under-deck triangular tied truss with central sagging chord, AL7075 section search, and X-bracing for buckling, fatigue and robustness.";
  return finalDes;
}

