                     (c > 0 && c >= t);
      if (isComp) {
        const u = num(mem.util, 0);
        if (u > m) m = u;
      }
    }
    return m;
  }

  function check(r, level) {
    if (!r || r.error || !r.ok) return false;
    if (r.robustness === false) return false;

    const mx = num(r.maxUtil, 1);
    const ac = num(r.alphaCr, 0);
    const fq = num(r.frequency, 0);
    const fw = num(r.fatigueWorst, 1);
    const cf = compWorst(r);

    let sagR = 1;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sagLimit > 0) {
      sagR = r.sag / r.sagLimit;
    }
    let swayR = 1;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.swayLimit > 0) {
      swayR = r.sway / r.swayLimit;
    }

    if (level === 2) {
      return mx <= 0.685 &&
             ac >= 8.0 &&
             fq >= 3.06 &&
             sagR <= 0.90 &&
             swayR <= 0.95 &&
             fw <= 0.655 &&
             cf <= 0.68;
    }
    return mx <= 0.72 &&
           ac >= 5.5 &&
           fq >= 3.00 &&
           sagR <= 0.98 &&
           swayR <= 1.02 &&
           fw <= 0.69 &&
           cf <= 0.72;
