  const MAX_CALLS = 400;
  let calls = 0;
  let best = null;
  const cache = new Map();

  function record(r, opt, specs) {
    if (!r || !r.ok || !check(r, 2)) return;
    const m = num(r.mass, Infinity);
    if (!best || m < best.mass - 1e-9) {
      best = {
        opt: cloneOpt(opt),
        specs: clone(specs),
        mass: m,
        r: r
      };
    }
  }

  function evalDesign(opt, specs, level) {
    const key = JSON.stringify({
      y: opt.y,
      pD: opt.presentD,
      pC: opt.presentC,
      side: opt.sidePattern,
      s: specs
    });
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAX_CALLS) return null;
    calls++;

    let r;
    try {
      const d = buildBase(opt, specs);
      r = analyse({
        note: d.note,
        nodes: d.nodes,
        members: d.members
      });
      if (r && !r.error) {
        r._keys = d.memberKeys;
      }
    } catch (e) {
      r = { error: String(e) };
    }

    cache.set(key, r);
    if (r && !r.error) record(r, opt, specs);
    return r;
  }

  function increaseGroup(opt, specs, g, level) {
    if (!active(opt, g)) return false;
    const cur = specs[g];
    if (!cur) return false;
    const curMass = massSpec(cur);
    const pool = groupPool(g);
    let bestCand = null;
    let bestMass = Infinity;
    for (const s of pool) {
      const m = massSpec(s);
      if (m > curMass + 1e-9 && m < bestMass) {
        bestMass = m;
        bestCand = s;
      }
    }
    if (!bestCand) return false;
    specs[g] = bestCand;
    return true;
  }

  function repair(opt, specs0, level, maxIter, budget) {
    let specs = clone(specs0);
    let r = evalDesign(opt, specs, level);

    for (let it = 0; it < maxIter && calls < budget; it++) {
      if (check(r, level)) return { specs: specs, r: r, ok: true };
      if (!r || r.error || !r.members) return { specs: specs, r: r, ok: false };

      let done = false;

      const fqMin = (level === 2) ? 3.06 : 3.00;
      const acMin = (level === 2) ? 8.0 : 5.5;
      if (num(r.frequency, 99) < fqMin || num(r.alphaCr, 99) < acMin) {
        const pref = ["d1","d0","c0","d2","c1","t0","t1","t2","b1","b2","end"];
        for (const g of pref) {
          if (specs[g] && active(opt, g) && increaseGroup(opt, specs, g, level)) {
            done = true;
            break;
          }
        }
      }

      if (!done) {
        let worstIdx = -1;
        let worstUtil = -1;
        for (let i = 0; i < r.members.length; i++) {
          const u = num(r.members[i].util, 0);
          if (u > worstUtil) {
            worstUtil = u;
            worstIdx = i;
          }
        }

        let g = null;
        if (worstIdx >= 0 && r._keys && r._keys[worstIdx]) {
          g = r._keys[worstIdx];
        }

        if (g && specs[g] && active(opt, g)) {
          if (!increaseGroup(opt, specs, g, level)) {
            for (const gg in specs) {
              if (specs[gg] && active(opt, gg) && increaseGroup(opt, specs, gg, level)) {
                done = true;
                break;
              }
            }
          } else {
            done = true;
          }
        } else {
          for (const gg in specs) {
            if (specs[gg] && active(opt, gg) && increaseGroup(opt, specs, gg, level)) {
              done = true;
              break;
            }
          }
        }
      }

      if (!done) return { specs: specs, r: r, ok: false };
      r = evalDesign(opt, specs, level);
    }

    return { specs: specs, r: r, ok: check(r, level) };
  }

  function shrink(opt, specs0, startR, level, order, passes, budget) {
    let specs = clone(specs0);
    let r = startR;

    for (let pass = 0; pass < passes; pass++) {
      let changed = false;

      for (let qi = 0; qi < order.length; qi++) {
        if (calls >= budget) break;
        const g = order[qi];
        if (!specs[g] || !active(opt, g)) continue;

        const pool = groupPool(g);
        const curMass = massSpec(specs[g]);
        let lo = 0;
        let hi = pool.length - 1;
        let ans = -1;

        while (lo <= hi && calls < budget) {
          const mid = (lo + hi) >> 1;
          const cm = massSpec(pool[mid]);

          if (cm >= curMass - 1e-9) {
            hi = mid - 1;
            continue;
          }

          const trial = clone(specs);
          trial[g] = pool[mid];
          const tr = evalDesign(opt, trial, level);

          if (tr && check(tr, level)) {
            ans = mid;
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        if (ans >= 0) {
          const cand = pool[ans];
          if (massSpec(cand) < curMass - 1e-9) {
            specs[g] = cand;
            r = evalDesign(opt, specs, level);
            changed = true;
          }
        }
      }

      if (!changed) break;
    }

    return { specs: specs, r: r };
  }

  function runTopo(opt, startSpecs, budget, order) {
    let specs = clone(startSpecs);
    let r = evalDesign(opt, specs, 2);

    if (!check(r, 2)) {
      const rep = repair(opt, specs, 2, 18, budget);
      specs = rep.specs;
      r = rep.r;
    }

    if (!check(r, 2)) {
      specs = clone(safeSeed);
      r = evalDesign(opt, specs, 2);
      if (!check(r, 2)) {
        const rep = repair(opt, specs, 2, 22, budget);
        specs = rep.specs;
        r = rep.r;
      }
    }

    if (check(r, 2)) {
      shrink(opt, specs, r, 2, order, 2, budget);
    }
  }

  const order1 = [
    "d0","d1","d2","c0","c1","c2","c3",
    "s1","s2","s3","sd1","sd2",
    "t0","t1","t2","end","b1","b2"
  ];
  const order2 = [
    "b1","b2","t0","t1","t2","end",
    "s1","s2","s3","sd1","sd2",
    "c0","c1","c2","c3","d0","d1","d2"
  ];

  const d0Opt = {
    y: yPar.slice(),
    presentD: [false, true, true],
    presentC: [true, true, true, true],
    sidePattern: "fwd"
  };
  const d1Opt = {
    y: yPar.slice(),
    presentD: [true, false, true],
    presentC: [true, true, true, true],
    sidePattern: "fwd"
  };
  const fullOpt = {
    y: yPar.slice(),
    presentD: [true, true, true],
    presentC: [true, true, true, true],
    sidePattern: "fwd"
  };
  const c0Opt = {
    y: yPar.slice(),
    presentD: [true, true, true],
    presentC: [false, true, true, true],
    sidePattern: "fwd"
  };

  runTopo(d0Opt, symSeed, 130, order1);
  runTopo(d1Opt, best ? clone(best.specs) : clone(symSeed), 240, order2);
  runTopo(fullOpt, symSeed, 330, order1);
  runTopo(c0Opt, best ? clone(best.specs) : clone(symSeed), 400, order2);

  const FALLBACK = {
    note: "Fallback attempt-5 central under-deck truss.",
    nodes: [
      {"id":"B1","x":3.483,"y":-1.855414,"z":0,"joint":"pin"},
      {"id":"B2","x":6.967,"y":-2.96896,"z":0,"joint":"pin"},
      {"id":"B3","x":10.45,"y":-3.34,"z":0,"joint":"pin"},
      {"id":"B4","x":13.933,"y":-2.96896,"z":0,"joint":"pin"},
