    ],
    members: [
      ["L0","L1","AL7075 CHS273x10"],["R0","R1","AL7075 CHS273x10"],
      ["L1","L2","AL7075 CHS273x10"],["R1","R2","AL7075 CHS273x10"],
      ["L2","L3","AL7075 CHS273x10"],["R2","R3","AL7075 CHS273x10"],
      ["L3","L4","AL7075 CHS273x10"],["R3","R4","AL7075 CHS273x10"],
      ["L4","L5","AL7075 CHS273x10"],["R4","R5","AL7075 CHS273x10"],
      ["L5","L6","AL7075 CHS273x10"],["R5","R6","AL7075 CHS273x10"],
      ["L0","R0","AL7075 CHS219.1x8"],
