      ["L1","B2","AL7075 CHS193.7x8"],["R1","B2","AL7075 CHS193.7x8"],
      ["L2","B3","AL7075 SHS100x8"],["R2","B3","AL7075 SHS100x8"],
      ["L3","B4","AL7075 CHS168.3x6.3"],["R3","B4","AL7075 CHS168.3x6.3"],
      ["L4","B5","AL7075 CHS193.7x8"],["R4","B5","AL7075 CHS193.7x8"],
