  if (best && best.mass < 4839 - 1e-6) {
    const out = buildBase(best.opt, best.specs);
    return {
      note: "Attempt 6: symmetric under-deck truss search with member-removal and mixed-section optimisation.",
      nodes: out.nodes,
      members: out.members
