    }
    heavies.sort((a, b) => b.m - a.m);

    const chordIdx = [];
    for (let i = 0; i < baseMembers.length; i++) {
      if (!bestPresent[i]) continue;
      if (i <= 11 || (i >= 19 && i <= 26)) chordIdx.push(i);
    }

    let trials = 0;
    let stop = false;

    for (let hi = 0; hi < heavies.length && !stop; hi++) {
      if (calls >= 394 || trials >= 10) break;
      const i = heavies[hi].i;
      const curMass = massSpec(bestSpecs[i]);

      let smallCand = null;
      for (const s of pool) {
        if (massSpec(s) < curMass * 0.62) smallCand = s;
        else break;
      }
      if (!smallCand) continue;

      for (const j of chordIdx) {
        if (calls >= 394 || trials >= 10) { stop = true; break; }
        if (i === j) continue;

        const curChordMass = massSpec(bestSpecs[j]);
        let bigCand = null;
        for (const s of pool) {
          if (massSpec(s) > curChordMass + 0.1) {
            bigCand = s;
            break;
          }
        }
        if (!bigCand) continue;

        const saved = (curMass - massSpec(smallCand)) * memberLen[i];
        const added = (massSpec(bigCand) - curChordMass) * memberLen[j];
        if (saved <= added + 0.5) continue;

        const trial = bestSpecs.slice();
        trial[i] = smallCand;
        trial[j] = bigCand;

        const tr = evalDesign(trial, bestPresent);
        trials++;

        if (tr && safe(tr) && tr.mass < bestMass - 1e-9) {
          bestMass = tr.mass;
          bestSpecs = trial;
          bestR = tr;
          break;
        }
      }
    }
  }

  function makeFallback() {
    return {
      note: "Verified attempt-5 central under-deck truss fallback (4839 kg).",
      nodes: baseNodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
      members: baseMembers.map(m => [m[0], m[1], m[2]])
    };
  }

  if (bestMass < baseMass - 1e-6 && bestR && safe(bestR)) {
    const outMembers = [];
    for (let i = 0; i < baseMembers.length; i++) {
      if (bestPresent[i] === false) continue;
      outMembers.push([baseMembers[i][0], baseMembers[i][1], bestSpecs[i]]);
    }
    return {
      note: "Per-member section and redundancy search around the verified central under-deck truss.",
      nodes: baseNodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: n.joint })),
      members: outMembers
    };
  }

  return makeFallback();
}

