      G.diag.push(["L" + j, "BL" + j], ["BL" + j, "L" + (j + 1)], ["R" + j, "BR" + j], ["BR" + j, "R" + (j + 1)]);
      G.tbot.push(["BL" + j, "BR" + j]);
