    const joints = {};
    if (t.rigid) for (let j = 0; j <= 6; j++) { joints["L" + j] = "rigid"; joints["R" + j] = "rigid"; }
    const members = [];
    for (const g of GROUPS) {
      const spec = L[g][idx[g]].spec;
      for (const [a, b] of G[g]) members.push({ a: a, b: b, spec: spec });
    }
    return { note: t.name, nodes: nodes, joints: joints, members: members };
  };

  const passMargins = (r) => {
    if (typeof r.maxUtil === "number" && r.maxUtil > UT) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.9 * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > 0.9 * r.swayLimit) return false;
    if (typeof r.frequency === "number" && r.frequency < 3.05) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < 5.5) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > 0.85) return false;
