    const startSpec = t.rigid ? "S690 CHS219.1x8" : "AL7075 CHS244.5x8";
    const idx = {};
    for (const g of GROUPS) {
      const k = L[g].findIndex((c) => c.spec === startSpec);
      idx[g] = k >= 0 ? k : L[g].length - 1;
    }
    let s = evalIdx(t, idx);
    for (let tries = 0; tries < 8 && s && !s.ok && !s.mech; tries++) {
