      }
      if (!changed || calls >= CAP) break;
    }
    return true;
  };

  searchTopo(TOPOS[0]);
  if (!best) searchTopo(TOPOS[1]);

  if (best) {
    const d = build(best.t, best.idx);
    d.note = best.t.name + " (analysed mass " + Math.round(best.mass) + " kg)";
    return d;
  }

  const L = listsFor(TOPOS[1]);
  const fb = {};
  for (const g of GROUPS) {
    const k = L[g].findIndex((c) => c.spec === "S690 CHS219.1x8");
    fb[g] = k >= 0 ? k : L[g].length - 1;
  }
  return build(TOPOS[1], fb);
