    return { pairs: pairs, grp: grp, V: V };
  };

  const build = (T, ix, note) => ({
    note: note,
    nodes: nodesOf(),
    joints: {},
    members: T.pairs.map((p, i) => ({ a: p[0], b: p[1], spec: LIST[ix[i]].spec }))
  });

  let calls = 0;
  const run = (T, ix) => {
    if (calls >= CAP || Date.now() - T0 > TLIM) return null;
    calls++;
    try {
      const r = analyse(build(T, ix, ""));
      return (r && !r.error) ? r : null;
    } catch (e) {
      return null;
    }
  };

  const utils = (T, r) => {
    if (!r || !Array.isArray(r.members)) return null;
    const map = {};
    r.members.forEach((m) => {
      if (m && m.id !== undefined) map[String(m.id).replace(/[\s\u2013\u2014]/g, "-")] = m;
    });
    const out = [];
    for (let i = 0; i < T.pairs.length; i++) {
      const a = T.pairs[i][0], b = T.pairs[i][1];
      let m = map[a + "-" + b] || map[b + "-" + a] || null;
      if (!m && r.members.length === T.pairs.length) m = r.members[i];
      const v = m ? Number(m.util) : NaN;
      out.push(isFinite(v) ? v : null);
    }
    return out;
  };

  const feasible = (r) => {
    if (!r || r.ok !== true || typeof r.mass !== "number") return false;
    if (r.robustness === false) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > UMAX) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > SAGF * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > SAGF * r.swayLimit) return false;
    if (typeof r.frequency === "number" && r.frequency < FMIN) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < ACRMIN) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > FATMAX) return false;
    return true;
  };

  // fully-stressed sizing loop; returns best feasible {ix, r} or null
  const sizeLoop = (T, ix0, maxIt) => {
    const M = T.pairs.length;
    let ix = ix0.slice();
    let r = run(T, ix);
    let best = null;
    const consider = (res, cur) => {
      if (feasible(res) && (best === null || res.mass < best.r.mass)) best = { ix: cur.slice(), r: res };
    };
    consider(r, ix);
    for (let it = 0; it < maxIt && r !== null; it++) {
      const u = utils(T, r);
      if (!u) break;
      const freqLow = typeof r.frequency === "number" && r.frequency < FMIN;
      const acrLow = typeof r.alphaCr === "number" && r.alphaCr < ACRMIN;
      const nix = ix.slice();
      let changed = false;
      for (let i = 0; i < M; i++) {
        const cur = ix[i];
        const g = T.grp[i];
        let k = cur;
        if (u[i] !== null) {
          const need = LIST[cur].A * Math.max(u[i], 0.02) / TARGET;
          let t = 0;
          while (t < NL - 1 && LIST[t].A < need) t++;
          if (t > cur + 3) t = cur + 3;
          if (t < cur - 3) t = cur - 3;
          k = t;
        }
        if ((freqLow && [0, 1, 3, 4, 5, 6].indexOf(g) >= 0) || (acrLow && [0, 1, 2].indexOf(g) >= 0)) {
          if (k <= cur) k = cur + 1;
        }
        k = Math.max(0, Math.min(NL - 1, k));
        if (k !== cur) { nix[i] = k; changed = true; }
      }
      if (!changed) break;
      ix = nix;
      r = run(T, ix);
      consider(r, ix);
    }
    return best;
  };

  // Phase 1: screen bracing variants
  const variants = [];
  for (const X of ["half", "full", "none"])
    for (const B of ["half", "full", "none"])
      for (const bc of [true, false]) variants.push({ X: X, B: B, bc: bc });

  let results = [];
  for (const V of variants) {
    if (calls > CAP - 40) break;
    const T = buildTopo(V);
    const ix0 = T.pairs.map((p, i) => startIdx(p[0], p[1], T.grp[i]));
    const b = sizeLoop(T, ix0, 10);
    if (b) results.push({ V: V, T: T, ix: b.ix, r: b.r });
  }
  results.sort((p, q) => p.r.mass - q.r.mass);

  // Phase 2: refine the two lightest feasible variants
  let champ = null;
  for (const c of results.slice(0, 2)) {
    if (calls > CAP - 40) break;
    const b = sizeLoop(c.T, c.ix, 14);
    const cand = b ? { V: c.V, T: c.T, ix: b.ix, r: b.r } : c;
    if (champ === null || cand.r.mass < champ.r.mass) champ = cand;
  }
  if (champ === null && results.length > 0) champ = results[0];

  // Phase 3: one shrink sweep, lowest utilisation first
  if (champ !== null) {
    const T = champ.T;
    let ix = champ.ix.slice();
    let r = champ.r;
    const u = utils(T, r);
    const uu = (i) => (u && u[i] !== null) ? u[i] : 0;
    const order = [];
    for (let i = 0; i < T.pairs.length; i++) order.push(i);
    order.sort((p, q) => uu(p) - uu(q));
    for (const i of order) {
      if (calls >= CAP || Date.now() - T0 > TLIM) break;
      if (ix[i] <= 0) continue;
      const trial = ix.slice();
      trial[i] = ix[i] - 1;
      const rr = run(T, trial);
      if (feasible(rr) && rr.mass < r.mass) { ix = trial; r = rr; }
    }
    champ = { V: champ.V, T: T, ix: ix, r: r };
    return build(champ.T, champ.ix,
      "AL7075 CHS/SHS pinned box truss, variant X=" + champ.V.X + " B=" + champ.V.B +
      " bottom-crossbeams=" + champ.V.bc + ", fully-stressed to util 0.68; analysed mass " +
      Math.round(champ.r.mass) + " kg");
  }

  const Tf = buildTopo({ X: "full", B: "full", bc: true });
  return build(Tf, Tf.pairs.map((p, i) => startIdx(p[0], p[1], Tf.grp[i])),
    "fallback: attempt-4 layout");
}

