    const x = +((j + 0.5) * P).toFixed(4);
    NODES.push({ id: "BL" + j, x: x, y: YB, z: ZL, joint: "pin" });
    NODES.push({ id: "BR" + j, x: x, y: YB, z: ZR, joint: "pin" });
  }

  // ix[i] = -1 means member removed
  const build = (ix, note) => {
    const members = [];
    const used = {};
    for (let i = 0; i < M; i++) {
      if (ix[i] >= 0) {
        members.push({ a: pairs[i][0], b: pairs[i][1], spec: LIST[ix[i]].spec });
        used[pairs[i][0]] = true;
        used[pairs[i][1]] = true;
      }
    }
    return { note: note, nodes: NODES.filter((n) => used[n.id]), joints: {}, members: members };
  };

  let calls = 0;
  const run = (ix) => {
    if (calls >= CAP || Date.now() - T0 > TLIM) return null;
    calls++;
    try {
      const r = analyse(build(ix, ""));
      return (r && !r.error) ? r : null;
    } catch (e) {
      return null;
    }
  };

  const feasible = (r) => {
    if (!r || r.ok !== true || typeof r.mass !== "number") return false;
    if (r.robustness === false) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > UMAX) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > SAGF * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > SAGF * r.swayLimit) return false;
    if (typeof r.frequency === "number" && r.frequency < FMIN) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < ACRMIN) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > FATMAX) return false;
    return true;
  };

  const utils = (r) => {
    if (!r || !Array.isArray(r.members)) return null;
    const map = {};
    r.members.forEach((m) => {
      if (m && m.id !== undefined) map[String(m.id).replace(/[\s\u2013\u2014]/g, "-")] = m;
    });
    return pairs.map((p) => {
      const m = map[p[0] + "-" + p[1]] || map[p[1] + "-" + p[0]] || null;
      const v = m ? Number(m.util) : NaN;
      return isFinite(v) ? v : null;
    });
  };

  const timeUp = () => calls >= CAP || Date.now() - T0 > TLIM;

  let cur = ix0.slice();
  let cr = run(cur);
  if (!feasible(cr)) {
    return build(ix0, "attempt-5 layout unchanged (baseline did not pass the margins)");
  }

  const tryMove = (trial) => {
    const rr = run(trial);
    if (feasible(rr) && rr.mass < cr.mass - 1e-6) {
      cur = trial;
      cr = rr;
      return true;
    }
    return false;
  };

  const removalPass = (maxU) => {
    const u = utils(cr);
    if (!u) return;
    const order = [];
    for (let i = 0; i < M; i++) {
      if (cur[i] >= 0 && u[i] !== null && u[i] <= maxU) order.push(i);
    }
    order.sort((p, q) => u[p] - u[q]);
    for (const i of order) {
      if (timeUp()) break;
      const t = cur.slice();
      t[i] = -1;
      tryMove(t);
    }
  };

  const shrinkPass = (maxU) => {
    const u = utils(cr);
    if (!u) return;
    const order = [];
    for (let i = 0; i < M; i++) {
      if (cur[i] > 0 && u[i] !== null && u[i] <= maxU) order.push(i);
    }
    order.sort((p, q) => u[p] - u[q]);
    for (const i of order) {
      if (timeUp()) break;
      const t = cur.slice();
      t[i] = cur[i] - 1;
      tryMove(t);
    }
  };

  removalPass(0.65);
  for (let s = 0; s < 4 && !timeUp(); s++) {
    const before = cr.mass;
    shrinkPass(0.67);
    removalPass(0.67);
    if (cr.mass > before - 1e-6) break;
  }

  return build(cur, "AL7075 CHS/SHS pinned box truss from attempt 5, greedy removal and one-step downsizing with margins (nominal max util <= 0.69, sag/sway <= 0.95 limit, frequency >= 2.95, alphaCr >= 5.5); analysed mass " + Math.round(cr.mass) + " kg");
}
